// Sales report. Used by the finance export (export.js) and the weekly digest (digest.js).
// The layout is parsed by the finance team's import, so do not move columns around.
// TODO: US region once the tax rules are clear

const SEPARATORS = {
  DE: { thousands: '.', decimal: ',' },
  FR: { thousands: ' ', decimal: ',' },
  UK: { thousands: ',', decimal: '.' },
};

// Report sections in output order.
const REGIONS = [
  { code: 'DE', title: 'Germany', taxRate: 0.19 },
  { code: 'FR', title: 'France', taxRate: 0.2 },
  { code: 'UK', title: 'United Kingdom', taxRate: 0.2 },
];

const PRODUCT_WIDTH = 20;
const UNITS_WIDTH = 5;
const MONEY_WIDTH = 14;
const BULK_UNITS = 100;
const BULK_FACTOR = 0.95;
const LARGE_ORDER = 10000;

const round2 = (n) => Math.round(n * 100) / 100;

export function formatMoney(amount, region) {
  const separators = SEPARATORS[region];
  if (!separators) {
    throw new Error('unknown region: ' + region);
  }
  let sign = '';
  if (amount < 0) {
    sign = '-';
    amount = -amount;
  }
  const fixed = amount.toFixed(2);
  const integerPart = fixed.slice(0, -3);
  const cents = fixed.slice(-2);
  const groups = [];
  for (let end = integerPart.length; end > 0; end -= 3) {
    groups.unshift(integerPart.slice(Math.max(0, end - 3), end));
  }
  const number = groups.join(separators.thousands) + separators.decimal + cents;
  return region === 'UK' ? sign + '£' + number : sign + number + ' €';
}

// Gross amount of one sale: discount, bulk rebate, then tax, rounded at each step.
function grossAmount(sale, taxRate) {
  let net = sale.units * sale.unitPrice;
  if (sale.discountPct) {
    net = net - (net * sale.discountPct) / 100;
  }
  if (sale.units >= BULK_UNITS) {
    net = net * BULK_FACTOR;
  }
  net = round2(net);
  const tax = round2(net * taxRate);
  return round2(net + tax);
}

function formatLine(sale, amount, region) {
  const name =
    sale.product.length > PRODUCT_WIDTH ? sale.product.slice(0, PRODUCT_WIDTH - 1) + '…' : sale.product;
  let line =
    name.padEnd(PRODUCT_WIDTH) +
    ' ' +
    String(sale.units).padStart(UNITS_WIDTH) +
    ' ' +
    formatMoney(amount, region).padStart(MONEY_WIDTH);
  if (amount >= LARGE_ORDER) {
    line += ' *';
  }
  return line;
}

export function buildReport(sales, options) {
  options = options || {};
  if (options.format && options.format !== 'text') {
    throw new Error('unsupported format: ' + options.format);
  }
  if (options.month && !/^\d{4}-\d{2}$/.test(options.month)) {
    throw new Error('bad month: ' + options.month);
  }

  const lines = [options.month ? 'SALES REPORT ' + options.month : 'SALES REPORT', ''];

  let data = sales.slice();
  if (options.month) {
    data = data.filter((s) => s.date.slice(0, 7) === options.month);
  }
  data.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));

  let rows = 0;
  let largeOrders = 0;

  for (const { code, title, taxRate } of REGIONS) {
    const regionSales = data.filter((s) => s.region === code && s.units > 0);
    if (regionSales.length === 0) continue;

    lines.push('== ' + title + ' ==');
    let subtotal = 0;
    for (const sale of regionSales) {
      const amount = grossAmount(sale, taxRate);
      lines.push(formatLine(sale, amount, code));
      subtotal += amount;
      rows++;
      if (amount >= LARGE_ORDER) largeOrders++;
    }
    lines.push('Subtotal ' + code + ': ' + formatMoney(subtotal, code));
    lines.push('');
  }

  if (rows === 0) {
    lines.push('No sales.');
  } else {
    lines.push('Rows: ' + rows);
    lines.push('Large orders: ' + largeOrders);
  }
  return lines.join('\n') + '\n';
}

